#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<ll> a(n),b(n),c(n);
        for(int i=0;i<n;i++) scanf("%lld %lld %lld",&a[i],&b[i],&c[i]);
        // lt[i][j]: f_i(x) < f_j(x) for all real x
        vector<vector<char>> lt(n, vector<char>(n,0));
        for(int i=0;i<n;i++) for(int j=0;j<n;j++) if(i!=j){
            ll A=a[j]-a[i], B=b[j]-b[i], C=c[j]-c[i];
            if(A==0) lt[i][j] = (B==0 && C>0);
            else lt[i][j] = (A>0 && B*B-4*A*C<0);
        }
        vector<int> L(n,0), R(n,0);
        function<int(int)> fl=[&](int j)->int{
            if(L[j]) return L[j];
            int best=0;
            for(int i=0;i<n;i++) if(lt[i][j]) best=max(best,fl(i));
            return L[j]=best+1;
        };
        function<int(int)> fr=[&](int i)->int{
            if(R[i]) return R[i];
            int best=0;
            for(int j=0;j<n;j++) if(lt[i][j]) best=max(best,fr(j));
            return R[i]=best+1;
        };
        for(int i=0;i<n;i++){ fl(i); fr(i); }
        for(int i=0;i<n;i++) printf("%d%c", L[i]+R[i]-1, i+1==n?'\n':' ');
    }
}

