    for(int i=0;i<n-1;i++){ int a,b; scanf("%d %d",&a,&b); E[i]={a,b}; g[a].push_back({b,i}); g[b].push_back({a,i}); }
    vector<int> par(n+1,0), pe(n+1,-1), order; vector<char> vis(n+1,0);
    order.push_back(1); vis[1]=1;
    for(size_t h=0;h<order.size();h++){ int v=order[h];
        for(auto [u,id]: g[v]) if(!vis[u]){ vis[u]=1; par[u]=v; pe[u]=id; order.push_back(u); } }
    vector<pair<int,int>> T; int lastRoot=-1;
    for(int v: order){ if(v==1) continue; int p=par[v];
        if(p==1){ if(lastRoot>=0) T.push_back({lastRoot,pe[v]}); lastRoot=pe[v]; }
        else T.push_back({pe[p],pe[v]}); }
