#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n; scanf("%d",&n);
    vector<pair<ll,int>> p(n);
    for(int i=0;i<n;i++){ scanf("%lld",&p[i].first); p[i].second=i+1; }
    int k; scanf("%d",&k);
    sort(p.begin(),p.end());
    vector<__int128> P1(n+1,0), P2(n+1,0);
    for(int j=0;j<n;j++){ P1[j+1]=P1[j]+p[j].first; P2[j+1]=P2[j]+(__int128)j*p[j].first; }
    __int128 best=0; int bl=-1;
    for(int l=0;l+k<=n;l++){
        __int128 s1=P1[l+k]-P1[l], s2=P2[l+k]-P2[l];
        // sum over window of x_j*(2*(j-l)-(k-1)) = pairwise distance sum
        __int128 cost = 2*(s2 - (__int128)l*s1) - (__int128)(k-1)*s1;
        if(bl<0 || cost<best){ best=cost; bl=l; }
    }
    for(int i=bl;i<bl+k;i++) printf("%d%c", p[i].second, i+1==bl+k?'\n':' ');
}

