int main(){
    ll n,m,i,j,a,b; cin>>n>>m>>i>>j>>a>>b;
    ll cx[2]={1,n}, cy[2]={1,m};
    ll best=-1;
    for(int p=0;p<2;p++) for(int q=0;q<2;q++){
        ll dx=cx[p]-i, dy=cy[q]-j;
        if(dx%a || dy%b) continue;
        ll tx=dx/a, ty=dy/b;
        ll Wx=(n-i)/a + (i-1)/a, Wy=(m-j)/b + (j-1)/b;   // width of allowed index range
        auto ok=[&](ll k, ll t, ll W)->bool{
            if(W==0) return k==0 && t==0;
            return k>=llabs(t) && (k-llabs(t))%2==0;
        };
        for(ll k=0;k<=2000005;k++) if(ok(k,tx,Wx) && ok(k,ty,Wy)){ if(best<0||k<best) best=k; break; }
    }
    if(best<0) cout<<"Poor Inna and pony!"<<endl; else cout<<best<<endl;
}

