#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n; ll m; scanf("%d %lld",&n,&m);
    vector<ll> a(n); for(auto &x:a) scanf("%lld",&x);
    sort(a.begin(),a.end());
    ll G=(n+m-1)/m;
    vector<ll> LS(G+1,0), RS(G+1,0);
    for(ll s=0;s<G;s++){ LS[s+1]=LS[s]+a[s*m]; RS[s+1]=RS[s]+a[n-1-s*m]; }
    ll best=LLONG_MAX;
    for(int k=0;k<n;k++){
        ll x=a[k];
        ll L=lower_bound(a.begin(),a.end(),x)-a.begin();
        ll R0=upper_bound(a.begin(),a.end(),x)-a.begin();
        ll cl=(L+m-1)/m, cr=(n-R0+m-1)/m;
        ll cost=(cl*x-LS[cl]) + (RS[cr]-cr*x);
        best=min(best,2*cost);
    }
    printf("%lld\n",best);
}

