using namespace std;
typedef long long ll;
// r row ops and c=k-r column ops: each row/column pair of ops costs p once, so
// total = (top-r row values) + (top-c column values) - p*r*c; greedy heaps give the top values.
int main(){
    int n,m; ll k,p; scanf("%d %d %lld %lld",&n,&m,&k,&p);
    vector<ll> R(n,0), C(m,0);
    for(int i=0;i<n;i++) for(int j=0;j<m;j++){ ll x; scanf("%lld",&x); R[i]+=x; C[j]+=x; }
    priority_queue<ll> hr(R.begin(),R.end()), hc(C.begin(),C.end());
    vector<ll> rp(k+1,0), cp(k+1,0);
    for(ll t=1;t<=k;t++){
        ll tp=hr.top(); hr.pop(); rp[t]=rp[t-1]+tp; hr.push(tp-p*m);
        ll tc=hc.top(); hc.pop(); cp[t]=cp[t-1]+tc; hc.push(tc-p*n);
    }
    ll best=LLONG_MIN;
    for(ll r=0;r<=k;r++){ ll c=k-r; best=max(best, rp[r]+cp[c]-p*r*c); }
    printf("%lld\n",best);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n,m,k; scanf("%d %d %d",&n,&m,&k);
    const ll INF=LLONG_MAX/4;
    vector<vector<pair<int,ll>>> g(n+1);
    vector<array<ll,3>> roads(m);
    for(int i=0;i<m;i++){ int u,v; ll x; scanf("%d %d %lld",&u,&v,&x); g[u].push_back({v,x}); g[v].push_back({u,x}); roads[i]={u,v,x}; }
    vector<ll> minT(n+1, INF);
    for(int i=0;i<k;i++){ int s; ll y; scanf("%d %lld",&s,&y); minT[s]=min(minT[s],y); g[1].push_back({s,y}); g[s].push_back({1,y}); }
    vector<ll> D(n+1,INF); D[1]=0;
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq; pq.push({0,1});
    while(!pq.empty()){
        auto [d,v]=pq.top(); pq.pop();
        if(d>D[v]) continue;
        for(auto [u,w]: g[v]) if(d+w<D[u]){ D[u]=d+w; pq.push({D[u],u}); }
    }
    // a train to s is needed only if its length equals D[s] and no road neighbour is tight
    vector<char> roadTight(n+1,0);
    for(auto &e: roads){
        int u=e[0], v=e[1]; ll w=e[2];
        if(D[u]+w==D[v]) roadTight[v]=1;
        if(D[v]+w==D[u]) roadTight[u]=1;
    }
    int kept=0;
    for(int s=2;s<=n;s++) if(minT[s]<INF && minT[s]==D[s] && !roadTight[s]) kept++;
    printf("%d\n", k-kept);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n;
    vector<string> nm(n), sn(n);
    for(auto &s:nm) cin>>s;
    for(auto &s:sn) cin>>s;
    sort(nm.begin(),nm.end()); sort(sn.begin(),sn.end());
    vector<int> cn(256,0), cs(256,0);
    for(auto &s:nm) cn[(unsigned char)s[0]]++;
    for(auto &s:sn) cs[(unsigned char)s[0]]++;
    auto mx=[&](){ int t=0; for(int c=0;c<256;c++) t+=min(cn[c],cs[c]); return t; };
    int M=mx();
    vector<char> used(n,0);
    string line;
    for(int i=0;i<n;i++){
        int l=(unsigned char)nm[i][0];
        cn[l]--;
        int chosen=-1;
        for(int j=0;j<n && chosen<0;j++){
            if(used[j]) continue;
            int s=(unsigned char)sn[j][0];
            cs[s]--;
            int gain=(s==l);
            if(mx()==M-gain){ chosen=j; M-=gain; }
            else cs[s]++;
        }
        used[chosen]=1;
        if(i) line+=", ";
        line+=nm[i]+" "+sn[chosen];
    }
    cout<<line<<endl;
}

#include <bits/stdc++.h>
using namespace std;
// 2-SAT: literal 2i = p_i in A, 2i+1 = p_i in B
int N; vector<vector<int>> g, gr; vector<int> ord, comp; vector<char> vis;
void dfs1(int v){ vis[v]=1; for(int u:g[v]) if(!vis[u]) dfs1(u); ord.push_back(v); }
void dfs2(int v,int c){ comp[v]=c; for(int u:gr[v]) if(comp[u]<0) dfs2(u,c); }
int main(){
    int n; long long a,b; scanf("%d %lld %lld",&n,&a,&b);
    vector<long long> p(n); for(auto &x:p) scanf("%lld",&x);
    map<long long,int> idx; for(int i=0;i<n;i++) idx[p[i]]=i;
    N=2*n; g.assign(N,{}); gr.assign(N,{});
    auto imp=[&](int u,int v){ g[u].push_back(v); gr[v].push_back(u); };
    auto clause=[&](int x,int y){ imp(x^1,y); imp(y^1,x); };   // x OR y
    for(int i=0;i<n;i++){
        long long x=p[i];
        // x in A => a-x in A
        if(idx.count(a-x)) clause(2*i+1, 2*idx[a-x]); else clause(2*i+1,2*i+1);
        // x in B => b-x in B
        if(idx.count(b-x)) clause(2*i, 2*idx[b-x]+1); else clause(2*i,2*i);
    }
    vis.assign(N,0); for(int v=0;v<N;v++) if(!vis[v]) dfs1(v);
    comp.assign(N,-1); int c=0;
    for(int k=N-1;k>=0;k--){ int v=ord[k]; if(comp[v]<0) dfs2(v,c++); }
    for(int i=0;i<n;i++) if(comp[2*i]==comp[2*i+1]){ printf("NO\n"); return 0; }
    printf("YES\n");
    for(int i=0;i<n;i++) printf("%d%c", comp[2*i]>comp[2*i+1]?0:1, i+1==n?'\n':' ');
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n; scanf("%d",&n);
    vector<string> pat(n); char buf[32];
    for(auto &s:pat){ scanf("%s",buf); s=buf; }
    ll prev=0; vector<ll> res;
    for(int idx=0; idx<n; idx++){
        const string &s=pat[idx]; int L=s.size();
        ll lb=prev+1; if(L>1) lb=max(lb,(ll)pow(10,L-1)+0LL);
        if(L==1) lb=max(lb,1LL);
        string d=to_string(lb);
        if((int)d.size()>L){ printf("NO\n"); return 0; }
        d=string(L-d.size(),'0')+d;
        // smallest string of length L matching s that is >= d
        string cand; bool ok=false;
        auto match=[&](const string &t){ for(int i=0;i<L;i++) if(s[i]!='?' && s[i]!=t[i]) return false; return true; };
        if(match(d)){ cand=d; ok=true; }
        else{
            vector<char> pre(L+1,0); pre[0]=1;
            for(int i=0;i<L;i++) pre[i+1]=pre[i] && (s[i]=='?' || s[i]==d[i]);
            for(int i=L-1;i>=0 && !ok;i--){
                if(!pre[i]) continue;
                for(int dg=d[i]-'0'+1; dg<=9 && !ok; dg++){
                    if(s[i]!='?' && s[i]-'0'!=dg) continue;
                    string t=d.substr(0,i); t+=char('0'+dg);
                    for(int j=i+1;j<L;j++) t+= (s[j]=='?' ? '0' : s[j]);
                    cand=t; ok=true;
                }
            }
        }
        if(!ok){ printf("NO\n"); return 0; }
        ll v=stoll(cand); res.push_back(v); prev=v;
    }
    printf("YES\n");
    for(ll v:res) printf("%lld\n", v);
}

#include <bits/stdc++.h>
using namespace std;
// each step: smallest number greater than the previous one with digit sum s (digit strings)
int main(){
    int n; scanf("%d",&n);
    string cur="";
    for(int it=0;it<n;it++){
        int s; scanf("%d",&s);
        int L=cur.size()+45;
        string x(L-cur.size(),'0'); x+=cur;
        vector<int> pre(L+1,0);
        for(int j=0;j<L;j++) pre[j+1]=pre[j]+(x[j]-'0');
        string res; bool found=false;
        for(int p=L-1;p>=0 && !found;p--){
            for(int d=x[p]-'0'+1; d<=9 && !found; d++){
                int rem=s-pre[p]-d, r=L-1-p;
                if(rem<0 || rem>9*r) continue;
                string t=x.substr(0,p); t.push_back('0'+d);
                string suf(r,'0'); int left=rem;
                for(int q=r-1;q>=0;q--){ int v=min(9,left); suf[q]='0'+v; left-=v; }
                res=t+suf; found=true;
            }
        }
        size_t st=res.find_first_not_of('0');
        cur=res.substr(st);
        printf("%s\n", cur.c_str());
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m; scanf("%d %d",&n,&m);
    vector<string> g(n);
    vector<char> buf(m+5);
    for(int i=0;i<n;i++){ scanf("%s",buf.data()); g[i]=buf.data(); }
    int dr[4]={0,0,1,-1}, dc[4]={1,-1,0,0};
    auto freeC=[&](int r,int c){ return r>=0&&r<n&&c>=0&&c<m&&g[r][c]=='.'; };
    vector<int> deg(n*m,0); queue<int> q;
    for(int r=0;r<n;r++) for(int c=0;c<m;c++) if(g[r][c]=='.'){
        int d=0; for(int k=0;k<4;k++) d+=freeC(r+dr[k],c+dc[k]);
        deg[r*m+c]=d; if(d==1) q.push(r*m+c);
    }
    while(!q.empty()){
        int id=q.front(); q.pop(); int r=id/m, c=id%m;
        if(g[r][c]!='.') continue;
        int f=-1;
        for(int k=0;k<4;k++) if(freeC(r+dr[k],c+dc[k])){ f=k; break; }
        if(f<0) continue;
        int r2=r+dr[f], c2=c+dc[f];
        if(f==0){ g[r][c]='<'; g[r2][c2]='>'; }
        else if(f==1){ g[r][c]='>'; g[r2][c2]='<'; }
        else if(f==2){ g[r][c]='^'; g[r2][c2]='v'; }
        else { g[r][c]='v'; g[r2][c2]='^'; }
        int cells[2][2]={{r,c},{r2,c2}};
        for(auto &pc: cells) for(int k=0;k<4;k++){
            int wr=pc[0]+dr[k], wc=pc[1]+dc[k];
            if(freeC(wr,wc)){ int w=wr*m+wc; if(--deg[w]==1) q.push(w); }
        }
    }
    for(int r=0;r<n;r++) for(int c=0;c<m;c++) if(g[r][c]=='.'){ printf("Not unique\n"); return 0; }
    for(int r=0;r<n;r++) printf("%s\n", g[r].c_str());
}

