int main(){
    ll C,Hr,Hb,Wr,Wb; cin>>C>>Hr>>Hb>>Wr>>Wb;
    ll hA=Hr,wA=Wr,hB=Hb,wB=Wb;
    if(hA*wB < hB*wA){ swap(hA,hB); swap(wA,wB); }   // A has the better joy per gram
    ll best=0;
    if(wA<=40000){
        for(ll y=0; y<=min(wA-1, C/wB); y++){ ll x=(C-y*wB)/wA; best=max(best, x*hA+y*hB); }
    } else {
        for(ll x=0; x<=C/wA; x++){ ll y=(C-x*wA)/wB; best=max(best, x*hA+y*hB); }
    }
    cout<<best<<endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n,m; scanf("%d %d",&n,&m);
    vector<int> eu(m),ev(m); vector<ll> ew(m);
    vector<vector<pair<int,int>>> g(n+1);
    for(int i=0;i<m;i++){ scanf("%d %d %lld",&eu[i],&ev[i],&ew[i]); g[eu[i]].push_back({ev[i],i}); g[ev[i]].push_back({eu[i],i}); }
    int s; scanf("%d",&s);
    const ll INF=LLONG_MAX/4;
    vector<ll> d(n+1,INF); d[s]=0;
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq; pq.push({0,s});
    while(!pq.empty()){
        auto [dv,v]=pq.top(); pq.pop();
        if(dv>d[v]) continue;
        for(auto [u,id]: g[v]){ ll nd=dv+ew[id]; if(nd<d[u]){ d[u]=nd; pq.push({nd,u}); } }
    }
    vector<ll> best(n+1,INF); vector<int> bid(n+1,-1);
    for(int i=0;i<m;i++){
        int a=eu[i], b=ev[i]; ll w=ew[i];
        if(d[a]+w==d[b] && w<best[b]){ best[b]=w; bid[b]=i; }
        if(d[b]+w==d[a] && w<best[a]){ best[a]=w; bid[a]=i; }
    }
    ll total=0; vector<int> chosen;
    for(int v=1;v<=n;v++) if(v!=s){ total+=best[v]; chosen.push_back(bid[v]+1); }
    printf("%lld\n",total);
    for(size_t i=0;i<chosen.size();i++) printf("%d%c",chosen[i], i+1==chosen.size()?'\n':' ');
}

