    int G=n-1;
    vector<ll> GL(G),GR(G);
    for(int i=0;i<G;i++){ GL[i]=l[i+1]-r[i]; GR[i]=r[i+1]-l[i]; }   // bridge length must lie in [GL,GR]
    vector<int> gi(G); iota(gi.begin(),gi.end(),0);
    sort(gi.begin(),gi.end(),[&](int x,int y){ return GL[x]<GL[y]; });
    vector<int> bi(m); iota(bi.begin(),bi.end(),0);
    sort(bi.begin(),bi.end(),[&](int x,int y){ return a[x]<a[y]; });
    vector<int> ans(G,-1);
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq;
    size_t p=0; int assigned=0; bool ok=true;
    for(int b: bi){
        ll x=a[b];
        while(p<gi.size() && GL[gi[p]]<=x){ pq.push({GR[gi[p]],gi[p]}); p++; }
        if(pq.empty()) continue;
        if(pq.top().first < x){ ok=false; break; }
        ans[pq.top().second]=b+1; pq.pop(); assigned++;
    }
    if(!ok || assigned!=G){ printf("No\n"); return 0; }
    printf("Yes\n");
    for(int i=0;i<G;i++) printf("%d%c", ans[i], i+1==G?'\n':' ');
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n;
    vector<string> a(n);
    for(auto &s:a) cin>>s;
    string d; cin>>d; char sep=d[0];
    long long total=0; for(auto &s:a) total+=s.size();
    int pairs=n/2, T=(int)(total/pairs);   // every line has len(x)+len(y)=T
    set<string> byLen[64];
    for(auto &s:a) byLen[s.size()].insert(s);
    auto charAt=[&](const string &x,const string &y,int k)->char{
        int lx=x.size(); if(k<lx) return x[k]; if(k==lx) return sep; return y[k-lx-1]; };
    for(int step=0;step<pairs;step++){
        const string *bx=nullptr,*by=nullptr;
        for(int l=1;l<T;l++){
            int ly=T-l; if(ly<1||ly>=64) continue;
            for(const string &x: byLen[l]){
                const string *yb=nullptr;
                for(auto it=byLen[ly].begin(); it!=byLen[ly].end(); ++it) if(*it!=x){ yb=&*it; break; }
                if(!yb) continue;
                if(!bx){ bx=&x; by=yb; continue; }
                bool less=false;
                for(int k=0;k<=T;k++){ char c1=charAt(x,*yb,k), c2=charAt(*bx,*by,k); if(c1!=c2){ less=c1<c2; break; } }
                if(less){ bx=&x; by=yb; }
            }
        }
        string X=*bx, Y=*by;
        byLen[X.size()].erase(X); byLen[Y.size()].erase(Y);
        cout<<X<<sep<<Y<<"\n";
    }
}
